    """Port of _per_job_argv."""
    if name == "lint":
        return (
            "env",
            "SKIP=agnix,lint-mermaid-fences,shellcheck",
            "make",
            "lint-only",
        )
    if name == "lint-mermaid":
        return ("make", "lint-mermaid")
